1.2 Data Types (String, Number, Boolean, Object, Array,
Null, Undefined, Symbol) - ប្រភេទទិន្ន័យ
JavaScript មានប្រភេទទិន្ន័យផ្សេងៗសម្
រាប់រក្សាទុកទិន្ន័យ។ ប្រភេទទិន្ន័យទាំំងនេះះរួមមាន String,
Number, Boolean, Object, Array, Null, Undefined, និង Symbol។ ការយល់ដឹងអំពីប្រភេទ
ទិន្ន័យគឺសំខាន់សម្
រាប់ការគ្រប់គ្រងទិន្ន័យឱ្យបានត្រឹឹមត្រូូវ។
ឧទាហរណ៍៖
// String: អក្សរឬឃ្លា
let greeting = "សួស្តីី";
// Number: លេខ (ទាំងគត់ និង ទសភាគ)
let price = 99.99;
// Boolean: តម្លៃ True ឬ False
let isStudent = true;
// Object: ទិន្ន័
យដែលមានលក្ខណៈសម្បត្តិិ
let person = { name: "Sokha", age: 25 };
// Array: បញ្ជីីទិន្ន័
យ
let fruits = ["ផ្លែប៉ោ
ម", "ចេក", "ស្វាយ"];
// Null: គ្មានតម្លៃ
let empty = null;
// Undefined: អថេរដែលមិនបានកំណត់តម្លៃ
let notAssigned;
// Symbol: តម្លៃតែមួយគត់
let id = Symbol("id");
console.log(typeof greeting); // string

