Special Operators - ប្រតិបត្តិិករពិសេស
ប្រតិបត្តិិករពិសេស (special operators) រួមមានប្រតិបត្តិិករដែលមានមុខងារពិសេស ដូចជា ,,
delete, in, new, និង void។
ឧទាហរណ៍៖
// Comma Operator
let a = (1, 2, 3);
console.log(a); // 3
// Delete Operator
let obj = { name: "Sokha" };
delete obj.name;
console.log(obj); // {}
// In Operator
let person = { age: 25 };
console.log("age" in person); // true
// New Operator
let date = new Date();
console.log(date); // Current date and time
// Void Operator
let result = void 0;
console.log(result); // undefined
ការពន្យល់៖, ប្រគល់តម្លៃចុងក្រោយ, delete លុបលក្ខណៈសម្បត្តិិ, in ពិនិត្យវត្តមានលក្ខណៈសម្បត្តិិ,
new បង្កើតវត្ថុថ្មីី, void ប្រគល់ undefined។

