សេចក្តីីបញ្ជាលក្ខណ្ឌ (conditional statements) នៅក្នុង JavaScript ត្រូូវបានប្រើដើម្បីីសម្រេចចិត្ត
ផ្អែកលើលក្ខណ្ឌ។ ប្រសិនបើលក្ខណ្ឌមួយពិត (true) កូដមួយផ្នែកនឹងត្រូូវប្រតិបត្តិិ ហើយបើមិនពិត (false)
កូដផ្នែកផ្សេងទៀទៀតអាចត្រូូវបានប្រតិបត្តិិ។ ផ្នែកនេះះនឹងផ្តោតលើ if, if else, និង if else if else ដើម្បីី
ជួយអ្នកយល់ពីការគ្រប់គ្រងលក្ខណ្ឌនៅក្នុងកម្មវិធី។ រាល់ឧទាហរណ៍នឹងបង្ហាញជាមួយកូដ ការពន្យល់លម្អិិត និង
លទ្ធផល។
2.1.1 Simple if Statement - សេចក្តីីបញ្ជា if សាមញ្ញ
if សាមញ្ញត្រូូវបានប្រើនៅពេលអ្នកចង់ប្រតិបត្តិិកូដតែនៅពេលលក្ខណ្ឌមួយពិត (true)។ ប្រសិនបើលក្ខណ្ឌមិន
ពិត កូដនៅក្នុង if នឹងត្រូូវរំលង។
ឧទាហរណ៍៖
let temperature = 30;
if (temperature > 25) {
    console.log("អាកាសធាតុក្តៅណាស់");
}
ការពន្យល់៖if (temperature > 25) ពិនិត្យថាតើសីតុណ្ហភាពធំជាង 25។ បើលក្ខណ្ឌពិត (true) កូដ
នៅក្នុងប្លុក នឹងប្រតិបត្តិិ ហើយបោះពុម្ព "អាកាសធាតុក្តៅណាស់"។ បើលក្ខណ្ឌមិនពិត គ្មានអ្វីីត្រូូវបានបោះពុម្ពទេ។
ក្នុងឧទាហរណ៍នេះះ temperature = 30 ដែលធំជាង 25 ដូច្នេះលក្ខណ្ឌពិត។
លទ្ធផល៖
អាកាសធាតុក្តៅណាស់
2.1.2 if else Statement - សេចក្តីីបញ្ជា if else
if else បន្ថែមផ្នែក else ដើម្បីីប្រតិបត្តិិកូដនៅពេលលក្ខណ្ឌរបស់ if មិនពិត (false)។ វាផ្តល់ជម្រើសពីរ
ផ្លូវ៖ មួយសម្
រាប់លក្ខណ្ឌពិត និងមួយទៀទៀតសម្
រាប់លក្ខណ្ឌមិនពិត។
ឧទាហរណ៍៖
let age = 16;
if (age >= 18) {
    console.log("អ្នកជាមនុស្សពេញវ័យ");
} else {
    console.log("អ្នកនៅតែជាអនីតិជន");
}

