items.body:
ការពន្យល់៖if (age >= 18) ពិនិត្យថាតើអាយុធំជាងឬស្
មើ 18។ បើលក្ខណ្ឌពិត បោះពុម្ព "អ្នកជាមនុស្ស
ពេញវ័យ"។ បើមិនពិត កូដក្នុង else នឹងប្រតិបត្តិិ ហើយបោះពុម្ព "អ្នកនៅតែជាអនីតិជន"។ ក្នុងឧទាហរណ៍នេះះ
age = 16 ដែលតូចជាង 18 ដូច្នេះ else ត្រូូវបានប្រតិបត្តិិ។
លទ្ធផល៖
អ្នកនៅតែជាអនីតិជន
2.1.3 if else if else Statement - សេចក្តីីបញ្ជា if else if else
if else if else អនុញ្ញាតឱ្យពិនិត្យលក្ខណ្ឌច្រើនជាងមួយ។ វាប្រើ else if ដើម្បីីបន្ថែមលក្ខណ្ឌបន្ទាប់
និង else សម្
រាប់ករណីដែលគ្មានលក្ខណ្ឌណាពិត។ នេះះជួយគ្រប់គ្រងស្ថានភាពស្មុគស្មាញដែលមានជម្រើស
ច្រើន។
ឧទាហរណ៍៖
let score = 75;
if (score >= 90) {
    console.log("អ្នកបាននិទ្ទេស A");
} else if (score >= 80) {
    console.log("អ្នកបាននិទ្ទេស B");
} else if (score >= 70) {
    console.log("អ្នកបាននិទ្ទេស C");
} else if (score >= 60) {
    console.log("អ្នកបាននិទ្ទេស D");
} else {
    console.log("អ្នកបាននិទ្ទេស F");
}
ការពន្យល់៖if (score >= 90) ពិនិត្យថាតើពិន្ទុធំជាងឬស្
មើ 90។ បើមិនពិត ពិនិត្យ else if (score
>= 80) ហើយបន្តទៅ else if ផ្សេងទៀទៀតតាមលំដាប់។ បើគ្មានលក្ខណ្ឌណាពិត else នឹងប្រតិបត្តិិ។ ក្នុង
ឧទាហរណ៍នេះះ score = 75 ដែលស្ថិិតនៅចន្លោះ 70 និង 79 ដូច្នេះ else if (score >= 70) ពិត
ហើយបោះពុម្ព "អ្នកបាននិទ្ទេស C"។
លទ្ធផល៖
អ្នកបាននិទ្ទេស C
2.1.4 Switch Statement - សេចក្តីីបញ្ជា Switch
សេចក្តីីបញ្ជា switch អនុញ្ញាតឱ្យជ្រើសរើសប្លុកកូដមួយក្នុងចំណោមប្លុកជាច្រើន ដោយផ្អែកលើតម្លៃនៃកន្សោម។
វាប្រៀៀបធៀធៀបតម្លៃមួយជាមួយ case ផ្សេងៗ ហើយប្រតិបត្តិិកូដនៅក្នុង case ដែលផ្គូផ្គង។ break ត្រូូវបានប្រើ

