let score = 75;
if (score >= 90) {
} else if (score >= 80) {
} else if (score >= 70) {
} else if (score >= 60) {
} else {
}

items.body:
ដើម្បីីបញ្ឈប់ការប្រតិបត្តិិ និងចាកចេញពី switch។ បើគ្មាន case ណាផ្គូផ្គងទេ default នឹងត្រូូវប្រតិបត្តិិ (បើ
មាន)។ នៅទីនេះះ យើងប្រើ switch ដើម្បីីកំណត់និទ្ទេសសិស្ស ស្រ
ដៀដៀងនឹង if else if else។
ឧទាហរណ៍៖
let score = 75;
switch (true) {
    case score >= 90:
        console.log("អ្នកបាននិទ្ទេស A");
        break;
    case score >= 80:
        console.log("អ្នកបាននិទ្ទេស B");
        break;
    case score >= 70:
        console.log("អ្នកបាននិទ្ទេស C");
        break;
    case score >= 60:
        console.log("អ្នកបាននិទ្ទេស D");
        break;
    default:
        console.log("អ្នកបាននិទ្ទេស F");
}
ការពន្យល់ / Explanation: switch (true) ពិនិត្យលក្ខណ្ឌនៅក្នុង case នីមួយៗ។ score = 75 ត្រូូវ
បានប្រៀៀបធៀធៀបជាមួយនឹង case នីមួយៗតាមលំដាប់។ case score >= 70 ពិត ដូច្នេះបោះពុម្ព "អ្នកបាន
និទ្ទេស C" ហើយ break បញ្ឈប់ការប្រតិបត្តិិ។ បើគ្មាន case ណាពិត (ឧ. score < 60) default នឹង
បោះពុម្ព "អ្នកបាននិទ្ទេស F"។ វិធីនេះះបង្ហាញពីការប្រើ switch សម្
រាប់លក្ខណ្ឌជួរ ស្រ
ដៀដៀងនឹង if else if
else។
លទ្ធផល / Output:
អ្នកបាននិទ្ទេស C
2.2 Loops (for, while, do...while, for...in, for...of) - រង្វិិលជុំ
រង្វិិលជុំ (loops) ត្រូូវបានប្រើដើម្បីីប្រតិបត្តិិកូដម្តងហើយម្តងទៀទៀតរហូតដល់លក្ខណ្ឌមួយត្រូូវបានបំពេញ។
JavaScript មាន for, while, do...while, for...in, និង for...of សម្
រាប់គ្រប់គ្រងការងារ
ដដែលៗ។
2.2.1 for Loop - រង្វិិលជុំ for

items.code:
let score = 75;
switch (true) {
    case score >= 90:
        break;
    case score >= 80:
        break;
    case score >= 70:
        break;
    case score >= 60:
        break;
}

for (let i = 0; i < 5; i++) {
}
let count = 0;
while (count < 5) {
    count++;
}

items.body:
do...while ប្រតិបត្តិិកូដយ៉ាងហោចម្តង មុននឹងពិនិត្យលក្ខណ្ឌ។
ឧទាហរណ៍៖
let num = 0;
do {
    console.log(`តម្លៃ: ${num}`);
    num++;
} while (num < 3);
ការពន្យល់៖ កូដក្នុង do ប្រតិបត្តិិម្តង មុននឹងពិនិត្យ while (num < 3)។ បន្ទាប់មក បន្តរង្វិិលជុំបើលក្ខណ្ឌ
ពិត។
