2.3 Break and Continue (Flow Control in Loops) - ការគ្រប់
គ្រងរង្វិិលជុំ (break, continue)
break និង continue ត្រូូវបានប្រើដើម្បីីគ្រប់គ្រងឥរិយាបថនៃរង្វិិលជុំ។ break បញ្ចប់រង្វិិលជុំទាំំងមូល ចំណែក
continue រំលងទៅវដ្តបន្ទាប់។
ឧទាហរណ៍៖
for (let i = 0; i < 10; i++) {
    if (i === 5) {
        break; // បញ្ចប់រង្វិលជុំនៅ i = 5
    }
    if (i === 3) {
        continue; // រំលង i = 3
    }
    console.log(`លេខ: ${i}`);
}
ការពន្យល់៖break បញ្ចប់រង្វិិលជុំនៅពេល i === 5 ដូច្នេះមិនបន្តទៅ i = 6 ឬបន្ទាប់។ continue រំលង
ការបោះពុម្ពនៅ i === 3 ប៉ុន្តែបន្តរង្វិិលជុំ។
