4. Objects - វត្ថុ
វត្ថុ (objects) នៅក្នុង JavaScript គឺជាទិន្ន័យដែលផ្ទុកលក្ខណៈសម្បត្តិិ (properties) និង
វិធីសាស្
ត្រ (methods) ដែលតំណាងឱ្យអង្គភាពមួយ។ វត្ថុជួយរៀរៀបចំទិន្ន័យឱ្យមានរបៀបៀប និង
អនុញ្ញាតឱ្យគ្រប់គ្រងទំនាក់ទំនងរវាងទិន្ន័យ និងអាកប្បកិរិយា។ ផ្នែកនេះះនឹងពន្យល់លម្អិិតអំពីការបង្កើត
វត្ថុ ការចូលប្រើលក្ខណៈសម្បត្តិិ វិធីសាស្
ត្រ ការបំបែកវត្ថុ (destructuring) ការប្រើ object
literals និង prototype សម្
រាប់មរតក។
4.1 Creating Objects - ការបង្កើតវត្ថុ
វត្ថុនៅក្នុង JavaScript អាចត្រូូវបានបង្កើតដោយប្រើ object literals ឬ constructor functions
និង new ពាក្យគន្លឹះ។ វិធីទាំំងនេះះអនុញ្ញាតឱ្យអ្នកកំណត់លក្ខណៈសម្បត្តិិ និងវិធីសាស្
ត្រសម្
រាប់វត្ថុ។
ឧទាហរណ៍៖
// Object Literal
const person = {
    name: "សុខា",
    age: 25
};
console.log(person);
// Constructor Function
function Car(model, year) {
    this.model = model;
    this.year = year;
}
const myCar = new Car("Toyota", 2020);
console.log(myCar);
ការពន្យល់៖object literal ប្រើ ដើម្បីីកំណត់វត្ថុដោយផ្ទាល់។ constructor function ប្រើ this
និង new ដើម្បីីបង្កើតវត្ថុជាមួយលក្ខណៈសម្បត្តិិដែលបានកំណត់។ ទាំំងពីរវិធីអនុញ្ញាតឱ្យអ្នកបង្កើតវត្ថុដែលផ្ទុក
ទិន្ន័យ។
លទ្ធផល៖
{ name: 'សុខា', age: 25 }
Car { model: 'Toyota', year: 2020 }

