4.5 Object Literals - វត្ថុលីតេរ៉ាល់
Object literals គឺជាវិធីសាមញ្ញបំផុតដើម្បីីបង្កើតវត្ថុដោយប្រើ ។ ES6 បានធ្វើឱ្យ object literals
កាន់តែសង្ខេបជាមួយនឹងការគាំំទ្រសម្
រាប់ឈ្
មោះអថេរដោយផ្ទាល់ និងវិធីសាស្
ត្រសង្ខេប។
ឧទាហរណ៍៖
const name = "សុខា";
const age = 25;
// Object Literal នៅក្នុង ES6
const person = {
    name, // សង្ខេបពី name: name
    age,
    greet() { // វិធីសាស្ត្រសង្ខេប
        console.log(`សួស្តីី ខ្ញុំំឈ្
មោះះ ${this.name}`);
    }
};
console.log(person);
person.greet();
ការពន្យល់៖name, age ជាការសង្ខេបនៃ name: name, age: age។ greet() ជាវិធីសាស្
ត្រសង្ខេប
ដែលលុប function ពាក្យគន្លឹះ។ Object literals ធ្វើឱ្យការបង្កើតវត្ថុកាន់តែសាមញ្ញ។
លទ្ធផល៖
{ name: 'សុខា', age: 25, greet: [Function: greet] }
សួស្តីី ខ្ញុំំឈ្
មោះះ សុខា
