5.2.5 map() - បង្កើតអារេថ្មីី
map() បង្កើតអារេថ្មីីដោយអនុវត្តអនុគមន៍ទៅលើធាតុនីមួយៗនៃអារេដើម ដោយមិនកែប្រែអារេដើម។
ឧទាហរណ៍៖
const numbers = [1, 2, 3];
const doubled = numbers.map(num => num * 2);
console.log(doubled);
console.log(numbers);
ការពន្យល់៖map បង្កើតអារេថ្មីីដែលមានធាតុនីមួយៗគុណនឹង 2។ អារេដើម numbers មិនត្រូូវបានកែប្រែទេ។
លទ្ធផល៖
[ 2, 4, 6 ]
[ 1, 2, 3 ]
5.2.6 filter() - ច្រោះធាតុ
filter() បង្កើតអារេថ្មីីដែលមានតែធាតុដែលឆ្លើយតបនឹងលក្ខណ្ឌជាក់លាក់។
ឧទាហរណ៍៖
const numbers = [1, 2, 3, 4, 5];
const even = numbers.filter(num => num % 2 === 0);
console.log(even);
console.log(numbers);
ការពន្យល់៖filter ជ្រើសរើសតែលេខគូបានពី numbers។ អារេថ្មីី even មានតែធាតុដែលបំពេញលក្ខណ្ឌ។
អារេដើមនៅដដែល។

