5.3 Array Destructuring - ការបំបែកអារេ
Array destructuring អនុញ្ញាតឱ្យអ្នកទាញធាតុចេញពីអារេទៅជាអថេរដោយផ្ទាល់ ធ្វើឱ្យកូដកាន់តែ
សង្ខេប។
ឧទាហរណ៍៖
const colors = ["ក្រ
ហម", "បៃតង", "ខៀវ"];
const [first, second] = colors;
console.log(first);
console.log(second);
// រំលងធាតុ
const [, , third] = colors;
console.log(third);
ការពន្យល់៖[first, second] ទាញធាតុទីមួយ និងទីពីរទៅជាអថេរ។ [, , third] រំលងធាតុទីមួយ និង
ទីពីរ ដើម្បីីទាញធាតុទីបី។
