5.4 Spread Operator (...) - ប្រតិបត្តិិករពន្លា
Spread operator (...) ពន្លាធាតុអារេទៅជាធាតុនីមួយៗ ឬចម្លងអារេទៅអារេថ្មីី។
ឧទាហរណ៍៖
const fruits = ["ផ្លែប៉ោ
ម", "ចេក"];
const moreFruits = [...fruits, "ស្វាយ"];
console.log(moreFruits);
const numbers = [1, 2];
const combined = [...numbers, ...fruits];
console.log(combined);
ការពន្យល់៖...fruits ពន្លាធាតុរបស់ fruits ទៅជាអារេថ្មីី។ spread operator អនុញ្ញាតឱ្យបញ្ចូល
អារេច្រើនជាមួយគ្នា ឬបន្ថែមធាតុថ្មីី។
លទ្ធផល៖
[ 'ផ្លែប៉ោ
ម', 'ចេក', 'ស្វាយ' ]
[ 1, 2, 'ផ្លែប៉ោ
ម', 'ចេក' ]
5.5 Rest Parameter in Functions - ប៉ារ៉ាម៉ែត្រសល់នៅក្នុង
អនុគមន៍
Rest parameter (...) ប្រមូលប៉ារ៉ាម៉ែត្រទាំំងអស់នៅក្នុងអនុគមន៍ទៅជាអារេ ដែលអនុញ្ញាតឱ្យគ្រប់គ្រង
ចំនួនប៉ារ៉ាម៉ែត្រមិនកំណត់។
ឧទាហរណ៍៖
function sum(...numbers) {
    return numbers.reduce((total, num) => total + num, 0);
}
console.log(sum(1, 2, 3));
console.log(sum(10, 20, 30, 40));

