6.3 Destructuring (Arrays and Objects) - ការបំបែក
Destructuring អនុញ្ញាតឱ្យអ្នកទាញតម្លៃចេញពីអារេ ឬវត្ថុទៅជាអថេរដោយផ្ទាល់ ធ្វើឱ្យកូដសង្ខេប និងអាន
បានងាយស្រួួ
ល។
ឧទាហរណ៍៖
// Array Destructuring
const colors = ["ក្រ
ហម", "បៃតង", "ខៀវ"];
const [first, second] = colors;
console.log(first, second);
// Object Destructuring
const person = { name: "សុខា", age: 25 };
const { name, age } = person;
console.log(name, age);
// ប្តូរឈ្
មោះះអថេរ
const { name: personName } = person;
console.log(personName);
ការពន្យល់៖[first, second] ទាញធាតុទីមួយ និងទីពីរពីអារេ។ ទាញលក្ខណៈសម្បត្តិិពីវត្ថុ។ name:
