    constructor(name, age) {
        this.name = name;
        this.age = age;
    }
    greet() {
        console.log(`សួស្តីី ខ្ញុំំឈ្
មោះះ ${this.name}`);
    }
    static info() {
        console.log("នេ
ះ
ះជាថ្នាក់ Person");
    }
}
// មរតក
class Student extends Person {
    constructor(name, age, grade) {
        super(name, age);
        this.grade = grade;
    }
    study() {
        console.log(`${this.name} កំពុងសិក្សា និទ្ទេស ${this.grade}`);
    }
}
const student = new Student("សុខា", 25, "A");
student.greet();

