8.3 Creating and Removing Elements: createElement(),
removeChild() - ការបង្កើត និងលុបធាតុ
createElement() បង្កើតធាតុ DOM ថ្មីី និង removeChild() លុបធាតុចេញពី DOM។ អ្នកអាចបន្ថែម
ធាតុដោយប្រើ appendChild() ឬ append()។
ឧទាហរណ៍៖
<!-- index.html -->
<div id="container">
    <p id="oldText">អក្សរចាស់</p>
</div>
const container = document.getElementById("container");
// បង្កើតធាតុថ្មីី
const newText = document.createElement("p");
newText.textContent = "អក្សរថ្មីី";
container.appendChild(newText);
// លុបធាតុ
const oldText = document.getElementById("oldText");
container.removeChild(oldText);
console.log(container.innerHTML);
ការពន្យល់៖createElement("p") បង្កើតធាតុ p ថ្មីី។ appendChild បន្ថែមវាទៅ container។
removeChild លុប oldText ចេញពី container។ លទ្ធផលបង្ហាញថា container មានតែអក្សរថ្មីី។
លទ្ធផល៖
