ការរៀរៀបចំកូដជាម៉ូឌុលជួយរក្សាកូដឱ្យមានរបៀបៀបរៀរៀបរយ និងអាចធ្វើមាត្រដ្ឋានបាន។ ម៉ូឌុលនីមួយៗគួរមានទំនួលខុស
ត្រូូវតែមួយ ដូចជាការគណនា ការគ្រប់គ្រង DOM ឬការទាញទិន្ន័យ។ ប្រើថតដើម្បីីរៀរៀបចំម៉ូឌុល និងឯកសារ
index.js ដើម្បីីប្រមូលនាំំចេញ។
ឧទាហរណ៍៖
project/
├── index.html
├── main.js
└── utils/
    ├── math.js
    └── dom.js
// utils/math.js
export const sum = (a, b) => a + b;
// utils/dom.js
export function updateText(id, text) {
    document.getElementById(id).textContent = text;
}
// main.js
import { sum } from './utils/math.js';
import { updateText } from './utils/dom.js';
console.log(sum(10, 20));
updateText('myDiv', 'សួស្តីី ពិភពលោក');
<!-- index.html -->
<div id="myDiv"></div>
<script type="module" src="main.js"></script>
ការពន្យល់៖ ថត utils រៀរៀបចំម៉ូឌុល math.js (សម្
រាប់ការគណនា) និង dom.js (សម្
រាប់ DOM)។
main.js នាំំចូលម៉ូឌុលទាំំងនេះះដើម្បីីប្រើ sum និង updateText។ ឧទាហរណ៍នេះះបង្ហាញការបូក និងធ្វើបច្ចុប្បន្ន
ភាពអក្សរនៅលើទំព័រ។
លទ្ធផល៖

