15.2 Constructor Functions - អនុគមន៍សាងសង់
Constructor functions គឺជាវិធីបែបបុរាណនៅក្នុង JavaScript ដើម្បីីបង្កើតវត្ថុ មុនពេលមាន class។
ពួកវាជាអនុគមន៍ធម្មតា ប៉ុន្តែប្រើជាមួយ new ដើម្បីីបង្កើតវត្ថុ។
ឧទាហរណ៍៖
function Car(brand, model) {
    this.brand = brand;
    this.model = model;
    this.drive = function() {
        return `${this.brand} ${this.model} កំពុងបើកបរ`;
    };
}
const car = new Car("Toyota", "Camry");
console.log(car.brand);

