15.3 Inheritance - ការទទួលមរតក
Inheritance អនុញ្ញាតឱ្យថ្នាក់មួយ (ថ្នាក់កូន) ទទួលលក្ខណៈសម្បត្តិិ និងវិធីសាស្
ត្រពីថ្នាក់មួយទៀទៀត (ថ្នាក់មេ)
ដោយប្រើ extends និង super។ វាជួយឱ្យកូដអាចប្រើឡើងវិញបាន។
ឧទាហរណ៍៖
class Animal {
    constructor(name) {
        this.name = name;
    }
    speak() {
        return `${this.name} បញ្ចេញសំឡេង`;
    }
}
class Dog extends Animal {
    constructor(name, breed) {
        super(name);
        this.breed = breed;
    }
    speak() {
        return `${this.name} ព្
រុស: វ៉ុុហ្វ!`;
    }
}

