15.4 Getters and Setters - អ្នកទទួល និងអ្នកកំណត់
Getters និង setters អនុញ្ញាតឱ្យគ្រប់គ្រងការចូលប្រើលក្ខណៈសម្បត្តិិដោយប្រើ get និង set។ ពួកវាផ្តល់
នូវវិធីសាស្
ត្រដើម្បីីទាញ ឬកំណត់តម្លៃជាមួយនឹងតក្កវិជ្ជាបន្ថែម។
ឧទាហរណ៍៖
class User {
    constructor(name) {
        this._name = name;
    }
    get name() {
        return this._name.toUpperCase();
    }
    set name(value) {
        if (value.length > 0) {
            this._name = value;
        } else {
            console.log("ឈ្
មោះះមិនអាចទទេបានទេ");
        }
    }
}
const user = new User("វណ្ណៈៈ");

