16.4 Error Stacks - ជង់កំហុស
Error stacks ផ្តល់នូវដាននៃការហៅអនុគមន៍ដែលនាំំទៅដល់កំហុស ដែលជួយកំណត់ទីតាំំងបញ្ហានៅក្នុងកូដ។
លក្ខណៈសម្បត្តិិ stack នៃវត្ថុ Error ផ្ទុកព័ត៌មាននេះះ។
ឧទាហរណ៍៖
function divide(a, b) {
    if (b === 0) {
        throw new Error("មិនអាចចែកជាមួយសូន្យបានទេ");
    }
    return a / b;
}
function calculate(a, b) {
    return divide(a, b);
}
try {
    calculate(10, 0);
} catch (error) {
    console.error("កំហុស:", error.message);
    console.log("ជង់កំហុស:", error.stack);
}
ការពន្យល់៖divide បោះកំហុសប្រសិនបើ b ជាសូន្យ೦। calculate ហៅ divide។ នៅពេលកំហុសកើត
ឡើង try-catch ចាប់វា និងបោះពុម្ព message និង stack។ stack បង្ហាញថា divide និង
calculate ត្រូូវបានហៅនៅទីតាំំងណា។
