18.4 Memoization - ការចងចាំំ
Memoization គឺជាបច្ចេកទេសរក្សាទុកលទ្ធផលនៃការគណនាដែលមានតម្លៃថ្លៃ ដើម្បីីជៀជៀសវាងការគណនាឡើង
វិញ។ វាប្រើ closure ដើម្បីីរក្សាឃ្លាំំងសម្ងាត់។
ឧទាហរណ៍៖
function memoize(fn) {
    const cache = {};
    return function(...args) {
        const key = JSON.stringify(args);
        if (key in cache) {
            return cache[key];
        }
        cache[key] = fn(...args);
        return cache[key];
    };
}
function fibonacci(n) {
    if (n <= 1) return n;
    return fibonacci(n - 1) + fibonacci(n - 2);
}
const memoFibonacci = memoize(fibonacci);

